import { test, expect } from '@playwright/test';

test.describe('Profile Settings - Timezone Setting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile');
  });

  test('should successfully set timezone and update profile settings', async ({ page }) => {
    // Verify timezone setting page is visible
    const timezoneSelect = page.getByRole('combobox', { name: /timezone/i });
    await expect(timezoneSelect).toBeVisible();

    // Verify current timezone is displayed
    const currentTimezoneLabel = page.getByText(/current timezone/i);
    await expect(currentTimezoneLabel).toBeVisible();

    // Verify timezone dropdown is populated
    const timezoneOptions = page.locator('[data-testid="timezone-options"]');
    await expect(timezoneOptions).toHaveCount(10);

    // Set timezone to a valid value
    const selectedTimezone = page.getByRole('option', { name: /Europe/i });
    await selectedTimezone.click();

    // Verify timezone is updated
    await expect(currentTimezoneLabel).toContainText(/Europe/i);

    // Verify timezone is saved
    const saveButton = page.getByRole('button', { name: /save changes/i });
    await expect(saveButton).toBeVisible();
    await saveButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/timezone updated successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify settings are saved
    const settingsButton = page.getByRole('button', { name: /settings/i });
    await expect(settingsButton).toBeVisible();

    // Navigate back to profile settings
    await settingsButton.click();

    // Verify timezone is still set
    await expect(currentTimezoneLabel).toContainText(/Europe/i);
  });

  test('should handle invalid timezone input and display error message', async ({ page }) => {
    // Verify timezone setting page is visible
    const timezoneSelect = page.getByRole('combobox', { name: /timezone/i });
    await expect(timezoneSelect).toBeVisible();

    // Verify current timezone is displayed
    const currentTimezoneLabel = page.getByText(/current timezone/i);
    await expect(currentTimezoneLabel).toBeVisible();

    // Verify timezone dropdown is populated
    const timezoneOptions = page.locator('[data-testid="timezone-options"]');
    await expect(timezoneOptions).toHaveCount(10);

    // Set invalid timezone (not in options)
    const invalidTimezoneOption = page.getByRole('option', { name: /invalid timezone/i });
    await invalidTimezoneOption.click();

    // Verify error message appears
    const errorMessage = page.getByText(/invalid timezone/i);
    await expect(errorMessage).toBeVisible();

    // Verify timezone dropdown still has valid options
    await expect(timezoneOptions).toHaveCount(10);

    // Verify save button is disabled
    const saveButton = page.getByRole('button', { name: /save changes/i });
    await expect(saveButton).toBeDisabled();

    // Verify user can still navigate back to settings
    const settingsButton = page.getByRole('button', { name: /settings/i });
    await expect(settingsButton).toBeVisible();

    // Navigate back to profile settings
    await settingsButton.click();

    // Verify error message is still visible
    await expect(errorMessage).toBeVisible();
  });
});
